"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import styles from "./BottomNav.module.css";

const TABS = [
  { href: "/", label: "Home", icon: "🏠" },
  { href: "/listings", label: "Listings", icon: "🔍" },
  { href: "/listings/new", label: "List", icon: "➕", emphasized: true },
  { href: "/dashboard", label: "My items", icon: "🗂️" },
];

function isTabActive(href: string, pathname: string): boolean {
  if (href === "/") return pathname === "/";
  if (href === "/listings") {
    return pathname === "/listings" || (pathname.startsWith("/listings/") && !pathname.startsWith("/listings/new"));
  }
  return pathname.startsWith(href);
}

export default function BottomNav() {
  const pathname = usePathname();

  return (
    <nav className={styles.nav} aria-label="Main navigation">
      {TABS.map((tab) => {
        const isActive = isTabActive(tab.href, pathname);
        return (
          <Link
            key={tab.href}
            href={tab.href}
            className={`${styles.link} ${isActive ? styles.linkActive : ""}`}
          >
            {tab.emphasized ? (
              <span className={styles.addIcon} aria-hidden="true">
                {tab.icon}
              </span>
            ) : (
              <span className={styles.icon} aria-hidden="true">
                {tab.icon}
              </span>
            )}
            {tab.label}
          </Link>
        );
      })}
    </nav>
  );
}
